## Event Handler
ابتدا بیایید نگاهی به مسیر API تعریف‌شده در فایل `api/events.ts` بیندازیم:

```js
import type { SlackEvent } from "@slack/web-api";
import {
  assistantThreadMessage,
  handleNewAssistantMessage,
} from "../lib/handle-messages";
import { handleNewAppMention } from "../lib/handle-app-mention";
import { verifyRequest, getBotId } from "../lib/slack-utils";
import type { Request, Response } from "express";

// Express handler for POST /api/events
export async function eventsHandler(req: Request, res: Response) {
  // Express provides parsed body if express.json() middleware is used
  const rawBody = JSON.stringify(req.body);
  const payload = req.body;
  const requestType = payload.type as "url_verification" | "event_callback";

  // See https://api.slack.com/events/url_verification
  if (requestType === "url_verification") {
    return res.status(200).send(payload.challenge);
  }

  // For Slack signature verification, we need the raw body and headers
  // The verifyRequest function may need to be updated to work with Express
  const valid = await verifyRequest({
    requestType,
    request: req,
    rawBody,
  });
  if (!valid) {
    return res.status(400).send("Invalid request");
  }

  try {
    const botUserId = await getBotId();

    const event = payload.event as SlackEvent;

    if (event.type === "app_mention") {
      void handleNewAppMention(event, botUserId);
    }

    if (event.type === "assistant_thread_started") {
      void assistantThreadMessage(event);
    }

    if (
      event.type === "message" &&
      !event.subtype &&
      event.channel_type === "im" &&
      !event.bot_id &&
      !event.bot_profile &&
      event.bot_id !== botUserId
    ) {
      void handleNewAssistantMessage(event, botUserId);
    }

    return res.status(200).send("Success!");
  } catch (error) {
    console.error("Error generating response", error);
    return res.status(500).send("Error generating response");
  }
}
```

```js
import { AppMentionEvent } from "@slack/web-api";
import { client, getThread } from "./slack-utils";
import { generateResponse } from "./generate-response";

const updateStatusUtil = async (
  initialStatus: string,
  event: AppMentionEvent,
) => {
  const initialMessage = await client.chat.postMessage({
    channel: event.channel,
    thread_ts: event.thread_ts ?? event.ts,
    text: initialStatus,
  });

  if (!initialMessage || !initialMessage.ts)
    throw new Error("Failed to post initial message");

  const updateMessage = async (status: string) => {
    await client.chat.update({
      channel: event.channel,
      ts: initialMessage.ts as string,
      text: status,
    });
  };
  return updateMessage;
};

export async function handleNewAppMention(
  event: AppMentionEvent,
  botUserId: string,
) {
  console.log("Handling app mention");
  if (event.bot_id || event.bot_id === botUserId || event.bot_profile) {
    console.log("Skipping app mention");
    return;
  }

  const { thread_ts, channel } = event;
  const updateMessage = await updateStatusUtil("is thinking...", event);

  if (thread_ts) {
    const messages = await getThread(channel, thread_ts, botUserId);
    const result = await generateResponse(messages, updateMessage);
    updateMessage(result);
  } else {
    const result = await generateResponse(
      [{ role: "user", content: event.text }],
      updateMessage,
    );
    updateMessage(result);
  }
}
```

## پیام‌های thread دستیار
زمانی که یک کاربر یک thread را با دستیار شما آغاز می‌کند، رویداد `assistant_thread_started` فعال می‌شود. تابع `assistantThreadMessage` در فایل `handle-messages.ts` مسئول مدیریت این نوع رویداد است.  
عملکرد این تابع به صورت زیر است:

- ارسال پیام خوش‌آمدگویی در ابتدای رشته
- ایجاد پیشنهادهای آماده (Suggested Prompts) برای کمک به کاربران جهت شروع تعامل با دستیار

در ادامه کد مربوط به تابع `assistantThreadMessage` آمده است:

```js
export async function assistantThreadMessage(
  event: AssistantThreadStartedEvent,
) {
  const { channel_id, thread_ts } = event.assistant_thread;
  console.log(`Thread started: ${channel_id} ${thread_ts}`);
  console.log(JSON.stringify(event));

  await client.chat.postMessage({
    channel: channel_id,
    thread_ts: thread_ts,
    text: "Hello, I'm an AI assistant built with the AI SDK by Vercel!",
  });

  await client.assistant.threads.setSuggestedPrompts({
    channel_id: channel_id,
    thread_ts: thread_ts,
    prompts: [
      {
        title: "Get the weather",
        message: "What is the current weather in London?",
      },
      {
        title: "Get the news",
        message: "What is the latest Premier League news from the BBC?",
      },
    ],
  });
}
```

## پیام‌های مستقیم (Direct Messages)
برای ارسال پیام‌های مستقیم (DM) به ربات، رویداد `message` فعال می‌شود. این رویداد توسط تابع `handleNewAssistantMessage` در فایل `handle-messages.ts` مدیریت می‌شود.  
عملکرد این تابع به صورت زیر است:

- بررسی اینکه پیام از یک ربات نیست تا از پاسخ‌دهی غیرضروری جلوگیری شود
- به‌روزرسانی وضعیت، برای نمایش اینکه پاسخ در حال تولید است
- بازیابی تاریخچه‌ی گفت‌وگو جهت ارائه‌ی Context به مدل
- فراخوانی LLM با استفاده از محتوای گفت‌وگو
- ارسال پاسخ LLM در thread مرتبط با پیام کاربر

در ادامه کد مربوط به تابع `handleNewAssistantMessage` آمده است:

```js
export async function handleNewAssistantMessage(
  event: GenericMessageEvent,
  botUserId: string,
) {
  if (
    event.bot_id ||
    event.bot_id === botUserId ||
    event.bot_profile ||
    !event.thread_ts
  )
    return;

  const { thread_ts, channel } = event;
  const updateStatus = updateStatusUtil(channel, thread_ts);
  updateStatus("is thinking...");

  const messages = await getThread(channel, thread_ts, botUserId);
  const result = await generateResponse(messages, updateStatus);

  await client.chat.postMessage({
    channel: channel,
    thread_ts: thread_ts,
    text: result,
    unfurl_links: false,
    blocks: [
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: result,
        },
      },
    ],
  });

  updateStatus("");
}
```

## منطق AI
هسته‌ی اصلی برنامه‌ی ما تابع `generateResponse` است که در فایل `lib/generate-response.ts` قرار گرفته است. این تابع وظیفه دارد پیام‌های دریافتی را پردازش کرده و با استفاده از AI SDK پاسخ مناسب تولید کند.  
نحوه‌ی پیاده‌سازی تابع `generateResponse` به شرح زیر است:

```js
import { createOpenAI } from '@ai-sdk/openai';
import { generateText } from 'ai';
import type { CoreMessage } from 'ai';

const my_model = createOpenAI({
  baseURL: process.env.BASE_URL,
  apiKey: process.env.LIARA_API_KEY,
});

export const generateResponse = async (
  messages: CoreMessage[],
  updateStatus?: (status: string) => void,
) => {
  const { text } = await generateText({
    model: my_model('openai/gpt-4o-mini'),
    system: `You are a Slack bot assistant. Keep your responses concise and to the point.
    - Do not tag users.
    - Current date is: ${new Date().toISOString().split('T')[0]}`,
    messages,
  });

  // Convert markdown to Slack mrkdwn format
  return text.replace(/\[(.*?)\]\((.*?)\)/g, '<$2|$1>').replace(/\*\*/g, '*');
};
```

در قطعه کد فوق، `BASE_URL` آدرس سرویس هوش مصنوعی است که از لیارا، تهیه کرده‌اید و  
مقدار `LIARA_API_KEY`، [کلید API کنسول](https://docs.liara.ir/references/api/about/#api-access-key) است.  
در قطعه کد فوق: 

- از تابع `generateText` در AI SDK برای فراخوانی مدل `openai/gpt-4o-mini` استفاده می‌شود
- یک system prompt ارائه شده است تا رفتار مدل را هدایت کند
- پاسخ نهایی به فرمت markdown سازگار با Slack قالب‌بندی شده است

## ارتقا LLM با Toolها
قدرت واقعی AI SDK در Toolهایی نهفته است که به ربات شما امکان انجام عملیات را می‌دهند. بیایید دو ابزار کاربردی به آن اضافه کنیم:

```js
import { createOpenAI } from '@ai-sdk/openai';
import { generateText, tool } from 'ai';
import { z } from 'zod';
import type { CoreMessage } from 'ai';

const my_model = createOpenAI({
  baseURL: process.env.BASE_URL,
  apiKey: process.env.LIARA_API_KEY,
});

export const generateResponse = async (
  messages: CoreMessage[],
  updateStatus?: (status: string) => void,
) => {
  const { text } = await generateText({
    model: my_model('openai/gpt-4o-mini:online'),
    system: `You are a Slack bot assistant. Keep your responses concise and to the point.
    - Do not tag users.
    - Current date is: ${new Date().toISOString().split('T')[0]}
    - Always include sources in your final response if you use web search.`,
    messages,
    maxSteps: 10,
    tools: {
      getWeather: tool({
        description: 'Get the current weather at a location',
        parameters: z.object({
          latitude: z.number(),
          longitude: z.number(),
          city: z.string(),
        }),
        execute: async ({ latitude, longitude, city }) => {
          updateStatus?.(`is getting weather for ${city}...`);

          const response = await fetch(
            `https://api.open-meteo.com/v1/forecast?latitude=${latitude}&longitude=${longitude}&current=temperature_2m,weathercode,relativehumidity_2m&timezone=auto`,
          );

          const weatherData = await response.json();
          return {
            temperature: weatherData.current.temperature_2m,
            weatherCode: weatherData.current.weathercode,
            humidity: weatherData.current.relativehumidity_2m,
            city,
          };
        },
      }),
    },
  });

  // Convert markdown to Slack mrkdwn format
  return text.replace(/\[(.*?)\]\((.*?)\)/g, '<$2|$1>').replace(/\*\*/g, '*');
};
```

## مدیریت تعاملات ربات با کاربر
همانطور که قبل‌تر گفته شد؛ فایل `index.ts` تعاملات ربات تلگرام با کاربران را مدیریت می‌کند. در این فایل، از کتابخانه `node-telegram-bot-api` برای ارتباط با API تلگرام استفاده شده است.
قطعه کد این فایل، در ادامه قرار گرفته است:

```js
import TelegramBot from 'node-telegram-bot-api';
import dotenv from 'dotenv';
import { translateWithFeedback } from './translator';

dotenv.config();

const bot = new TelegramBot(process.env.TELEGRAM_BOT_TOKEN!, { polling: true });

type UserState = {
  step: 'idle' | 'awaitingText' | 'awaitingTargetLanguage';
  sourceText?: string;
};

const userStates = new Map<number, UserState>();

bot.onText(/\/start/, (msg) => {
  const chatId = msg.chat.id;
  bot.sendMessage(
    chatId,
    `سلام ${msg.from?.first_name || ''} 👋\nبه ربات مترجم خوش اومدی!\nاز منو یکی از دستورات رو انتخاب کن.`,
    {
      reply_markup: {
        keyboard: [
          [{ text: '/translate' }, { text: '/help' }],
        ],
        resize_keyboard: true,
      },
    }
  );
  userStates.set(chatId, { step: 'idle' });
});

bot.onText(/\/translate/, (msg) => {
  const chatId = msg.chat.id;
  bot.sendMessage(chatId, '📝 لطفاً متنی که می‌خوای ترجمه بشه رو وارد کن');
  userStates.set(chatId, { step: 'awaitingText' });
});

bot.onText(/\/help/, (msg) => {
  const chatId = msg.chat.id;

  const helpMessage = `
🤖 راهنمای ربات:

✅ /start - شروع و نمایش منوی اصلی
🌐 /translate - ترجمه متن به زبان دلخواه
ℹ️ /help - نمایش این راهنما
  `.trim();

  bot.sendMessage(chatId, helpMessage);
});

bot.on('message', async (msg) => {
  const chatId = msg.chat.id;
  const text = msg.text?.trim();

  if (!text || text.startsWith('/')) return;

  const state = userStates.get(chatId) || { step: 'idle' };

  if (state.step === 'awaitingText') {
    userStates.set(chatId, { step: 'awaitingTargetLanguage', sourceText: text });
    bot.sendMessage(chatId, '🌐 حالا زبان مقصد رو وارد کن (مثلاً: فارسی، انگلیسی و...)');
    return;
  }

  if (state.step === 'awaitingTargetLanguage' && state.sourceText) {
    bot.sendMessage(chatId, '⏳ در حال ترجمه...');

    try {
      const result = await translateWithFeedback(state.sourceText, text);
      const t = result.currentObjectTranslation.translation;

      const message = `
✅ ترجمه نهایی:

📝 ${t.accurate_translated_text}

------------------------
🌐 زبان متن اصلی: ${t.text_language}
🔁 زبان مقصد: ${t.target_language}
🔤 متن اصلی:
${t.text_to_translate}

💡 توضیحات (به زبان مقصد):
${t.explanations_related_to_translation_in_target_language}
      `.trim();

      bot.sendMessage(chatId, message);
    } catch (err) {
      bot.sendMessage(chatId, '❌ خطایی در ترجمه رخ داد.');
      console.error(err);
    }

    userStates.set(chatId, { step: 'idle' });
  }
});
```

## ربات مترجم
اکنون بیایید ببینیم 
در هر ارسال درخواست ربات تلگرام به مدل، چه اتفاقی می‌افتد. فایل `translator.ts` مسئول ارتباط با LLM است. قطعه کد این فایل، در ادامه، قرار گرفته است:

```js
import { generateText, generateObject } from 'ai';
import { createOpenAI } from '@ai-sdk/openai';
import { z } from 'zod';
import dotenv from 'dotenv';

dotenv.config();

const my_model = createOpenAI({
  baseURL: process.env.BASE_URL!,
  apiKey: process.env.LIARA_API_KEY!,
});

const translationSchema = z.object({
  translation: z.object({
    text_language: z.string(),
    text_to_translate: z.string(),
    target_language: z.string(),
    accurate_translated_text: z.string(),
    explanations_related_to_translation_in_target_language: z.string(),
  }),
});

export async function translateWithFeedback(text: string, targetLanguage: string) {
  let currentTranslation = '';
  let currentObjectTranslation = { translation: {
    text_language: '',
    text_to_translate: text,
    target_language: targetLanguage,
    accurate_translated_text: '',
    explanations_related_to_translation_in_target_language: '',
  }};
  let iterations = 0;
  const MAX_ITERATIONS = 3;

  const { object: firstTranslation } = await generateObject({
    model: my_model('openai/gpt-4o-mini'),
    system: `You are an expert literary translator.
    You Do not censor any content in the translation and provide the correct and accurate text.`,
      prompt: `Translate this text to ${targetLanguage}, preserving tone and cultural nuances:\n\n${text}`,
    schema: translationSchema,
  });

  currentTranslation = firstTranslation.translation.accurate_translated_text;
  currentObjectTranslation = firstTranslation as {
    translation: {
      text_language: string;
      text_to_translate: string;
      target_language: string;
      accurate_translated_text: string;
      explanations_related_to_translation_in_target_language: string;
    };
  };

  while (iterations < MAX_ITERATIONS) {
    const { object: evaluation } = await generateObject({
      model: my_model('openai/gpt-4.1-mini'),
      schema: z.object({
        qualityScore: z.number().min(1).max(10),
        preservesTone: z.boolean(),
        preservesNuance: z.boolean(),
        culturallyAccurate: z.boolean(),
        specificIssues: z.array(z.string()),
        improvementSuggestions: z.array(z.string()),
      }),
      system: 'You are an expert in evaluating literary translations.',
      prompt: `Evaluate this translation:\n\nOriginal: ${text}\nTranslation: ${currentTranslation}\n\nConsider:\n1. Overall quality\n2. Preservation of tone\n3. Preservation of nuance\n4. Cultural accuracy`,
    });

    if (
      evaluation.qualityScore >= 8 &&
      evaluation.preservesTone &&
      evaluation.preservesNuance &&
      evaluation.culturallyAccurate
    ) {
      break;
    }

    const { object: improvedTranslation } = await generateObject({
      model: my_model('openai/gpt-4.1'),
      system: 'You are an expert literary translator.',
      prompt: `Improve this translation based on the following feedback:\n\n${evaluation.specificIssues.join('\n')}\n\n${evaluation.improvementSuggestions.join('\n')}\n\nOriginal: ${text}\nCurrent Translation: ${currentTranslation}`,
      schema: translationSchema,
    });

    currentTranslation = improvedTranslation.translation.accurate_translated_text;
    currentObjectTranslation = improvedTranslation as {
      translation: {
        text_language: string;
        text_to_translate: string;
        target_language: string;
        accurate_translated_text: string;
        explanations_related_to_translation_in_target_language: string;
      };
    };
    iterations++;
  }

  return {
    currentObjectTranslation,
    iterations,
  };
}
```

