        ];

        $results = [];

        foreach ($databases as $connection => $env) {
            try {
                Config::set('database.connections.' . $connection, [
                    'driver' => env($env . '_CONNECTION', 'mariadb'),
                    'host' => env($env . '_HOST', '127.0.0.1'),
